mapper.select:
select password from sys_user_pwd_history
where user_id = #{userId}
order by history_id desc
limit #{limit}

mapper.delete:
delete from sys_user_pwd_history
where user_id = #{userId}
  and history_id not in (
      select history_id from sys_user_pwd_history
      where user_id = #{userId}
      order by history_id desc
      limit #{keep}
  )
